package com.github.tartaricacid.touhoulittlemaid.init;
import net.minecraft.stats.Achievement;import net.minecraftforge.common.AchievementPage;
/** Native 1.7 replacement for the core modern advancements. */
public final class ModAchievements{public static Achievement TAME_MAID,BOARD_WIN,DEVOTED,RESURRECT;private ModAchievements(){}public static void init(){TAME_MAID=new Achievement("achievement.tlm_tame_maid","tlm_tame_maid",0,0,ModItems.CAMERA,null).initIndependentStat().registerStat();BOARD_WIN=new Achievement("achievement.tlm_board_win","tlm_board_win",2,1,ModItems.GOMOKU_BOARD_STATE,TAME_MAID).registerStat();DEVOTED=new Achievement("achievement.tlm_devoted","tlm_devoted",2,-1,ModItems.ULTRAMARINE_ORB_ELIXIR,TAME_MAID).setSpecial().registerStat();RESURRECT=new Achievement("achievement.tlm_resurrect","tlm_resurrect",4,0,ModItems.FILM,TAME_MAID).registerStat();AchievementPage.registerAchievementPage(new AchievementPage("Touhou Little Maid",TAME_MAID,BOARD_WIN,DEVOTED,RESURRECT));}}
